import { useContext, useEffect, useState } from 'react';
import AuthContext from '../context/AuthContext';
import axios from 'axios';

function Dashboard() {
  const { user } = useContext(AuthContext);
  const [resumes, setResumes] = useState([]);

  useEffect(() => {
    async function load() {
      try {
        const res = await axios.get('http://localhost:5001/api/resume/my', { withCredentials: true });
        setResumes(res.data.data);
      } catch (err) {
        console.error(err);
      }
    }
    if (user) load();
  }, [user]);

  if (!user) return <div style={{ padding: 20 }}>Please login to view your dashboard</div>;

  return (
    <div className="page mt-0">
      <section className="bg-slate-50 pt-16 pb-12 border-b border-border-light">
        <div className="container">
          <h1 className="text-2xl mb-2">Candidate <span className="text-accent">Success Console</span></h1>
          <p className="muted italic font-medium">Monitoring analysis for {user.name || user.email}</p>
        </div>
      </section>

      <div className="container py-16">
        <div className="max-w-5xl mx-auto">
          {resumes.length === 0 ? (
            <div className="card text-center py-20" style={{ borderStyle: 'dashed', borderWidth: '2px' }}>
              <div className="mb-6 mx-auto w-16 h-16 bg-accent-soft rounded-full flex items-center justify-center text-accent">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M13 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"></path><polyline points="13 2 13 9 20 9"></polyline></svg>
              </div>
              <h3 className="text-lg mb-2">No Active Profiles Detected</h3>
              <p className="muted mb-8">Deploy your first resume to trigger the match intelligence engine.</p>
              <button className="btn btn-primary px-10" onClick={() => window.location.href = '/upload'}>Initialize Upload</button>
            </div>
          ) : (
            <div className="space-y-8">
              {resumes.map(r => (
                <div key={r._id} className="card overflow-hidden" style={{ padding: 0 }}>
                  <div className="flex flex-col md:flex-row">
                    <div className="w-full md:w-56 p-8 flex flex-col items-center justify-center text-center bg-slate-50 border-r border-border-light">
                      <span className="text-[10px] uppercase font-black tracking-widest muted mb-4">Competency Index</span>
                      <div className="text-4xl font-black mb-2" style={{ color: r.score >= 70 ? 'var(--success)' : (r.score >= 40 ? 'var(--warning)' : 'var(--danger)') }}>
                        {Math.round(r.score || 0)}%
                      </div>
                      <span className={`badge px-3 py-1 ${r.score >= 70 ? 'bg-success' : 'bg-secondary'}`} style={{ fontSize: '9px' }}>
                        {r.score >= 70 ? 'High Affinity' : 'Developing'}
                      </span>
                    </div>

                    <div className="flex-1 p-8">
                      <div className="flex justify-between items-start mb-6">
                        <div>
                          <h4 className="text-lg font-black mb-1">{r.jobId?.title || 'General Profile Analysis'}</h4>
                          <p className="small muted font-bold uppercase tracking-tight">System Ref: {r._id?.slice(-8).toUpperCase()}</p>
                        </div>
                        <span className={`badge ${r.interviewStatus === 'Shortlisted' ? 'bg-success' : 'bg-secondary'}`}>
                          {r.interviewStatus}
                        </span>
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-8 mb-8">
                        <div>
                          <span className="block text-[10px] muted uppercase font-black mb-3">Core Strengths</span>
                          <div className="flex flex-wrap gap-1.5">
                            {(r.matchedSkills || r.skills || []).slice(0, 5).map((s, i) => (
                              <span key={i} className="chip" style={{ fontSize: '10px', padding: '5px 10px' }}>{s}</span>
                            ))}
                          </div>
                        </div>
                        <div>
                          <span className="block text-[10px] muted uppercase font-black mb-3">Gap Mitigation</span>
                          <div className="flex flex-wrap gap-1.5">
                            {(r.missingSkills || []).length > 0 ? (
                              (r.missingSkills || []).slice(0, 3).map((s, i) => (
                                <span key={i} className="chip missing" style={{ fontSize: '10px', padding: '5px 10px' }}>{s}</span>
                              ))
                            ) : (
                              <span className="small text-success font-bold italic">Optimal alignment verified</span>
                            )}
                          </div>
                        </div>
                      </div>

                      <div className="flex justify-between items-center pt-6 border-t border-border-light">
                        <span className="text-[10px] muted uppercase font-black">Applied {new Date(r.createdAt).toLocaleDateString()}</span>
                        <button className="btn btn-ghost py-2 text-xs">Access Full Intelligence Profile</button>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
